import pyomo.environ as pyo

DATA = {
    "products": ["regular", "premium"],
    "profit": {"regular": 20, "premium": 50},
    "max_demand": {"regular": 80, "premium": 50},
    "max_supply": 120,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.PRODUCTS = pyo.Set(initialize=d["products"])

    def profit_bounds(m, p):
        return (0, None)

    model.production = pyo.Var(
        model.PRODUCTS,
        domain=pyo.NonNegativeReals,
        bounds=profit_bounds,
    )

    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.PRODUCTS)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.maximize)

    def demand_rule(m, p):
        return m.production[p] <= d["max_demand"][p]

    model.demand_limit = pyo.Constraint(model.PRODUCTS, rule=demand_rule)

    def supply_rule(m):
        return sum(m.production[p] for p in m.PRODUCTS) <= d["max_supply"]

    model.supply_limit = pyo.Constraint(rule=supply_rule)

    return model
